INSERT INTO public.places (title, slug, short_description, description, why_visit, region, city, location_text, category, suitable_for, best_time, duration, approximate_cost, difficulty, local_secret, owner_id, status, created_at)
VALUES
('Tyulenovo Cliffs','tyulenovo-cliffs','Sun-bleached rock arches and sea caves where the Black Sea turns an improbable shade of blue.','A small fishing village on the northern Black Sea coast, framed by low limestone cliffs, natural arches and sea caves. There is no beach in the classic sense — people swim straight off the rocks into deep, very clear water. Walking north or south along the cliff edge quickly leaves the village behind.','Dramatic coastline without resorts, crowds or sunbeds.','Dobrich Province','Tyulenovo','Northern Black Sea coast, near Shabla','Sea','{"Couples","Photographers","Solo travellers"}','Late spring to early autumn','2-3 h','Free','Easy',NULL,NULL,'published', now() - interval '8 hours'),
('Kovachevitsa','kovachevitsa','A preserved stone village of timber balconies and slate roofs high in the Rhodopes.','An architectural reserve village in the western Rhodopes, built from stone and timber on a steep forested slope. Narrow cobbled lanes, tall houses with wooden balconies and slate roofs have been kept largely intact, which is why the village is often used as a film location.','One of the best preserved traditional villages in Bulgaria.','Blagoevgrad Province','Kovachevitsa','Western Rhodope Mountains, near Gotse Delchev','Hidden Gems','{"Couples","Families","Photographers"}','Spring and autumn','Half day','Free','Easy',NULL,NULL,'published', now() - interval '7 hours'),
('Devil''s Bridge','devils-bridge','An Ottoman-era arch spanning the Arda gorge, wrapped in morning mist and older legends.','A 16th-century stone bridge over the Arda river, built on the old road between the Aegean and the Thracian plain. The main arch and its reflection form a near circle in calm water, and mist often gathers in the gorge early in the day. Local legends give the bridge its name.','A striking piece of Ottoman engineering in a quiet river gorge.','Kardzhali Province','Ardino','Arda river gorge, near Ardino','History & Culture','{"Couples","Photographers","Solo travellers"}','Early morning, spring or autumn','1-2 h','Free','Easy',NULL,NULL,'published', now() - interval '6 hours'),
('Belogradchik Rocks','belogradchik-rocks','Towering sandstone pillars that swallow a medieval fortress and glow deep red at sunset.','A long belt of red sandstone and conglomerate formations in north-western Bulgaria, shaped into towers, walls and figures. The Belogradchik Fortress is built directly into the rocks, using them as natural ramparts, and the upper platforms give wide views over the surrounding hills.','Bulgaria''s most spectacular rock landscape combined with a fortress.','Vidin Province','Belogradchik','North-western Bulgaria, Balkan foothills','Best Views','{"Families","Photographers","Hikers"}','Late afternoon for the best light','2-3 h','€','Moderate',NULL,NULL,'published', now() - interval '5 hours'),
('Shiroka Laka','shiroka-laka','Whitewashed Rhodope houses, bagpipe schools and slow meals beside a mountain river.','A village strung along a narrow river valley in the central Rhodopes, known for its white houses with dark timber balconies and for its long musical tradition. Small family taverns serve Rhodope staples such as patatnik, cheverme and thick bean soup.','Traditional Rhodope architecture, music and mountain cooking.','Smolyan Province','Shiroka Laka','Central Rhodope Mountains, near Smolyan','Food & Wine','{"Couples","Families","Food lovers"}','Winter for atmosphere, summer for walks','3-4 h','Free','Easy',NULL,NULL,'published', now() - interval '4 hours'),
('Beglik Tash','beglik-tash','A Thracian rock sanctuary hidden in oak forest a short walk from the sea.','A megalithic Thracian sanctuary on the Strandzha coast, made of large weathered stone blocks arranged around a natural clearing. A marked circular path leads between the formations through low oak forest, with the sea visible through the trees.','Ancient Thracian ritual site in an unusually peaceful coastal setting.','Burgas Province','Primorsko','Strandzha coast, north of Primorsko','Photo Spots','{"Couples","Families","Photographers"}','Early morning light','1-2 h','€','Easy',NULL,NULL,'published', now() - interval '3 hours'),
('Krushuna Waterfalls','krushuna-waterfalls','Terraced travertine cascades falling through green forest on wooden walkways.','A cascade system near the village of Krushuna, where mineral-rich water has built stepped travertine terraces over thousands of years. A wooden walkway follows the stream past pools and small falls, with a steeper path climbing to the upper cascade and nearby caves.','The largest travertine waterfall cascade in Bulgaria.','Lovech Province','Krushuna','Northern Bulgaria, near Letnitsa','Nature','{"Families","Photographers","Hikers"}','Spring, when water levels are highest','2-3 h','€','Easy',NULL,NULL,'published', now() - interval '2 hours'),
('Prohodna Cave','prohodna-cave','A through-cave whose twin openings in the ceiling look like a pair of eyes.','A karst tunnel cave above the Iskar gorge, open at both ends and crossed on foot in a few minutes. Two eye-shaped holes in the ceiling, known as the Eyes of God, let daylight fall into the main gallery, and the cave is also used for climbing and bungee jumping.','One of the most photographed natural formations in the country.','Lovech Province','Karlukovo','Iskar gorge, near Karlukovo','Nature','{"Families","Photographers","Solo travellers"}','Midday, when light falls through the openings','1-2 h','Free','Easy',NULL,NULL,'published', now() - interval '1 hour');